CREATE OR REPLACE FUNCTION public.can_manage_company_pl_access(_user_id uuid DEFAULT auth.uid()) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT _user_id IN ('09ee800b-b7b2-4c81-9eb5-9ec11c472516'::uuid, 'a3a66a1c-c247-4803-8a56-634b568bd286'::uuid) AND public.has_role(_user_id, 'admin') AND EXISTS (SELECT 1 FROM public.profiles WHERE id = _user_id AND is_archived IS NOT TRUE); $$;
REVOKE ALL ON FUNCTION public.can_manage_company_pl_access(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.can_manage_company_pl_access(uuid) TO authenticated, service_role;
CREATE TABLE public.company_pl_access (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, granted_by uuid NOT NULL REFERENCES public.profiles(id), granted_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.company_pl_access TO authenticated;
GRANT ALL ON public.company_pl_access TO service_role;
ALTER TABLE public.company_pl_access ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Jamie or recipient reads P&L grant" ON public.company_pl_access FOR SELECT TO authenticated USING (public.can_manage_company_pl_access(auth.uid()) OR user_id = auth.uid());
CREATE OR REPLACE FUNCTION public.has_company_pl_access(_user_id uuid DEFAULT auth.uid()) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT public.can_manage_company_pl_access(_user_id) OR (public.is_staff(_user_id) AND EXISTS (SELECT 1 FROM public.profiles WHERE id = _user_id AND is_archived IS NOT TRUE) AND EXISTS (SELECT 1 FROM public.company_pl_access WHERE user_id = _user_id)); $$;
ALTER POLICY "Jamie imports company P&L" ON public.company_pl_workbooks WITH CHECK (public.can_manage_company_pl_access(auth.uid()) AND imported_by = auth.uid());
CREATE OR REPLACE FUNCTION public.list_company_pl_access() RETURNS TABLE(user_id uuid, full_name text, email text, has_access boolean, is_manager boolean) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NOT public.can_manage_company_pl_access(auth.uid()) THEN RAISE EXCEPTION 'Only Jamie can manage P&L access' USING ERRCODE = '42501'; END IF; RETURN QUERY SELECT p.id, p.full_name, p.email, public.has_company_pl_access(p.id), public.can_manage_company_pl_access(p.id) FROM public.profiles p WHERE p.is_archived IS NOT TRUE AND public.is_staff(p.id) ORDER BY p.full_name NULLS LAST, p.email; END; $$;
CREATE OR REPLACE FUNCTION public.set_company_pl_access(_user_id uuid, _enabled boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NOT public.can_manage_company_pl_access(auth.uid()) THEN RAISE EXCEPTION 'Only Jamie can manage P&L access' USING ERRCODE = '42501'; END IF; IF public.can_manage_company_pl_access(_user_id) THEN RAISE EXCEPTION 'Jamie retains P&L access'; END IF; IF _enabled IS NULL THEN RAISE EXCEPTION 'Choose an access setting'; END IF; IF _enabled THEN IF NOT public.is_staff(_user_id) OR NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = _user_id AND is_archived IS NOT TRUE) THEN RAISE EXCEPTION 'Select active staff'; END IF; INSERT INTO public.company_pl_access(user_id, granted_by) VALUES (_user_id, auth.uid()) ON CONFLICT (user_id) DO NOTHING; ELSE DELETE FROM public.company_pl_access WHERE user_id = _user_id; END IF; END; $$;
REVOKE ALL ON FUNCTION public.list_company_pl_access() FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.set_company_pl_access(uuid, boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.list_company_pl_access() TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.set_company_pl_access(uuid, boolean) TO authenticated, service_role;